    this.resetDocStore(to.fullPath);
    this.restoreBeforeLeave();
    await this.removeCache();
    next();
  },
  mounted: async function () {
    this.locale = this.getSelectedLanguage();

    let doc_id = this.$route.params.id as string;
    this.getDocAnnotations(doc_id);
    await this.fetchAttributes(this.record.doc_type);
    this.getDocTypeAllSettings();

    window.addEventListener('resize', this.windowResize);
    document.body.addEventListener('click', this.mouseClicked, true);

    (<any>window).rda = this;
    this.acquireDocLock();
    this.init();

    document.addEventListener('new_log', this.addNewLog);
    document.addEventListener('keydown', this.keyDownEvent);
    // document.addEventListener('handle_correction_button', this.addNewLog);

    for (let x = 1; x <= 80; x++) {
      this.fontSizes.push(x.toString() + 'pt');
    }
  },
  unmounted: function () {
    window.removeEventListener('resize', this.windowResize);
    document.removeEventListener('new_log', this.addNewLog);
    document.removeEventListener('keydown', this.keyDownEvent);
    // document.removeEventListener('handle_correction_button', this.addNewLog);
  },
  methods: {
    openImageInSeparateWindow() {
      let route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    sortStampsByLanguage() {
      let lang = this.$i18n.language;
      let sorted: any = [];
      if (lang == DEFAULT_LANGUAGE) {
        lang = 'en';
      }
      this.stamps.forEach((stamp: string) => {
        if (lang != 'de' && lang != 'en') {
          lang = 'en';
        }
        if (stamp.includes(lang)) {
          sorted.push(stamp);
        }
      });
      this.selectedStamp = sorted[0];
      this.sortedStamps = sorted;
    },
    async init() {
      this.isSecondApproval();
      if (!this.$route.params.id) {
        this.$router.push('/dashboard');
      }

      if (this.second_approval) {
        this.filter_status = CONSTANTS.approved_pending_second_approval;
      }

      this.docId = this.$route.params.id as string;
      const loaded = await this.getInvoiceDataByDocId(this.docId);
      // The store already renders an error banner when the document is
      // missing. Stop before building the layout/model against an empty record.
      if (!loaded) {
        return;
      }
      await this.getFieldsPermissions(this.record.doc_type);

      const { layoutType, filterStatus } = layoutTypeForDocumentStatus(
        this.record.status,
        !!this.model[approve_before_export_v2],
      );
      if (filterStatus) {
        this.filter_status = filterStatus;
      }

      this.renderPendingRecordsCountView();
      this.renderNextPrevLinkBtns();

      await this.startSettingsFetch();
      await this.getFormBuilderLayout(layoutType);
      await this.populateListsAndValues();

      this.renderComponent = true;
      if (readOnlyDocStatus.includes(this.record.status)) {
        this.isReadOnly = true;
      }

      this.handleImageBaseURL();
      this.image =
        this.baseUrl + '/' + cleanUpImagePath(this.record.images[0].path);
      this.images = cleanUpImagesUrl(this.record.images);
      this.sortStampsByLanguage();

      // set the width of image
      this.windowResize();
    },

    isSecondApproval() {
      this.second_approval = false;
      if (
        this.$route.params.second_approval &&
        this.$route.params.second_approval === 'true'
      ) {
        this.second_approval = true;
      }
    },

    async getInvoiceDataByDocId(docId: string): Promise<boolean> {
      try {
        this.showLoading();
        await this.getDocumentById(docId);
        // The store surfaces missing/deleted documents through its own error
        // banner. Don't also raise a raw toast on top of it.
        if (this.error) {
          return false;
        }
        if (!this.record.doc_id) {
          throw { message: 'INVALID_DOCUMENT' };
        }
        return true;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return false;
      } finally {
        this.hideLoading();
      }
    },

    fillFirstApprover() {
      let fieldDef = {} as dynamicObj;
      if (this.record.first_approver) {
        if (
          this.record.document_approval &&
          this.record.document_approval.approval_requests &&
          this.record.document_approval.approval_requests.length > 0 &&
          this.record.document_approval.approvals
        ) {
          fieldDef = this.createEmptyField(
            'first_approver',
            '',
            this.record.assigned_to,
          );
        } else {
          fieldDef = this.createEmptyField(
            'first_approver',
            '',
            this.record.first_approver,
          );
        }
      } else {
        fieldDef = this.createEmptyField(
          'assigned_to',
          '',
          this.record.assigned_to,
        );
      }

      return fieldDef;
    },

    createEmptyField(name: string, type = '', value: any = '') {
      if (type == 'checkbox') {
        value = false;
      }
      return {
        confidence: 0,
        name: name,
        value: value,
        formatted_value: value,
        content: value,
      };
    },
    async getAssignToUsers() {
      await this.dropdownStore.prepareUsersDropdown();
      this.usersList = this.dropdownStore.usersList;
      this.formBuilderModel['assigned_to'] = this.getUserFullName(
        this.record.assigned_to,
      );
      this.setPreviousApprover();
    },

    setPreviousApprover() {
      if (!this.second_approval) {
        return;
      }

      if (this.record.first_approver) {
        this.formBuilderModel['first_approver'] = this.getUserFullName(
          this.record.first_approver,
        );
      }
    },
    async getFieldsPermissions(document_type: string) {
      try {
        if (!document_type) {
          return;
        }
        const response = await documentDetailApiService.getFieldsPermissionsApi(document_type);
        if (!response.success) {
          throw { message: response.message };
        }

        this.field_permissions = response.field_permissions;
        this.general_permissions = response.general;
        this.prepareFieldPermissions(response.field_permissions);
        this.prepareTablePermissions(response.table_column_permissions);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    prepareTablePermissions(permissions: any) {
      if (!permissions) {
        return;
      }

      for (const [index, item] of Object.entries(permissions)) {
        const permission = item as any;
        let name = permission.name.toLowerCase();
        this.tablePermissions[name] = { id: index, access: permission.access };
      }
    },
    prepareFieldPermissions(permissions: any) {
      if (!permissions) {
        return;
      }

      for (const [index, item] of Object.entries(permissions)) {
        const permission = item as any;
        let name = permission.name.toLowerCase();
        this.fieldPermissions[name] = { id: index, access: permission.access };
      }
    },

    filterUserList(val: string, update: any, abort: any) {
      try {
        if (val === '') {
          update(() => {
            this.usersList = this.dropdownStore.usersList;
          });
          return;
        }

        update(() => {
          const needle = val.toLowerCase();
          this.usersList = this.dropdownStore.usersList.filter(
            (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
          );
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        abort();
      }
    },
    getUserFullName(id: number) {
      let userInfo = this.dropdownStore.usersList.filter((v: any) => {
        return v.value == id;
      });

       
      return userInfo[0].label;
    },
    isModelReady() {
      return objLen(this.formBuilderConfigModel) !== 0;
    },
    goHelp() {
      window.open('https://docs.cloudintegration.eu/');
    },

    keyDownEvent(e: any) {
      if (e.key === 'd' && e.ctrlKey) {
        this.toggleSideBar('activity_stream');
      }
    },
    htmlElementClick(fieldName: string) {
      if (
        this.formBuilderConfigModel[fieldName].fieldType ===
        formBuilderInputTypes.BUTTON
      ) {
        this.handleButtons(fieldName);
        return;
      }
    },
    handleButtons(fieldName: string) {
      if (this.isReadOnly) {
        return;
      }

      if (this.formBuilderConfigModel[fieldName].type == CONSTANTS.reject) {
        this.rejectRequest();
        return;
      }

      if (this.formBuilderConfigModel[fieldName].type == CONSTANTS.save) {
        this.saveData();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type == CONSTANTS.request_release
      ) {
        this.acceptRequest();
        return;
      }

      if (this.formBuilderConfigModel[fieldName].type == CONSTANTS.in_review) {
        this.setInReview();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type ==
        CONSTANTS.restart_workflow
      ) {
        this.goToFieldValidation();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type ==
        CONSTANTS.reject_and_correct
      ) {
        this.rejectAndCorrect();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type ==
        CONSTANTS.approve_and_correct
      ) {
        this.approveAndCorrect();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type == CONSTANTS.view_summery
      ) {
        this.goToSummery();
        return;
      }

      if (
        this.formBuilderConfigModel[fieldName].type == CONSTANTS.export_and_next
      ) {
        this.exportAndNext();
        return;
      }
      if (
        this.formBuilderConfigModel[fieldName].type ==
        CONSTANTS.notify_requisitioner
      ) {
        this.notifyRequisition();
        return;
      }
    },
    onInputValueChanges(field_name: string, fieldType: string) {
      if (fieldType == formBuilderInputTypes.NOTES) {
        return;
      }
      this.updateLocalModel(field_name);
      this.updateImportJson(field_name);
    },

    updateLocalModel(field_name: string) {
      if (!this.formBuilderModel.hasOwnProperty(field_name)) {
        return;
      }
      this.formBuilderModel[field_name].value =
        this.formBuilderModel[field_name].formatted_value;
    },

    updateImportJson(
      connectionId: string,
      coordinates?: any,
      page?: number,
      extractionMethod = '',
    ) {
      try {
        const found_field = this.record.fields.find(
          (field: any) => field.name === connectionId,
        ) as dynamicObj;
        if (!found_field) {
          this.record.fields.push({});

          const field_index = this.record.fields.length - 1;
          this.record.fields[field_index].name = connectionId;
          this.record.fields[field_index].content =
            this.formBuilderModel[connectionId].content;
          this.record.fields[field_index].formatted_value =
            this.formBuilderModel[connectionId].formatted_value;
          this.record.fields[field_index].value =
            this.formBuilderModel[connectionId].value;
          this.record.fields[field_index].original_value = '';
          this.record.fields[field_index].validation_code = '';
          this.record.fields[field_index].extraction_method = extractionMethod;
          this.record.fields[field_index].is_validated = true;
          this.record.fields[field_index].is_valid = true;
          this.record.fields[field_index].color = CONSTANTS.success_border_left;

          if (this.formBuilderModel[connectionId].multi_line === true) {
            this.record.fields[field_index].multi_line = true;
          } else {
            this.record.fields[field_index].multi_line = false;
          }

          if (coordinates) {
            this.record.fields[field_index].coords = coordinates;
          }

          if (page) {
            this.record.fields[field_index].page = page;
          }

          this.$emit('checkFieldInvalid', this.record.fields[field_index]);
          return;
        }

        // existing field
        if (!found_field.hasOwnProperty('original')) {
          found_field['original'] = Object.assign({}, found_field);
        }

        if (!found_field.hasOwnProperty('original_value')) {
          found_field['original_value'] = found_field.value;
        }

        if (coordinates || coordinates === null) {
          found_field.coords = coordinates;
        }

        if (page) {
          found_field.page = page;
        }
        if (extractionMethod) {
          found_field.extraction_method = extractionMethod;
        }

        found_field.is_valid = true;
        found_field.is_validated = true;

        let field = this.formBuilderModel[connectionId];
        found_field.formatted_value = field.formatted_value;
        found_field.value = field.value ? field.value : field.formatted_value;
        found_field.content = field.content;

        if (!(field.hasOwnProperty('api_save') && field.api_save)) {
          found_field.value = field.formatted_value;
        }

        if (
          isUndefinedOrNull(found_field.formatted_value) ||
          isEmptyString(found_field.formatted_value)
        ) {
          found_field.content = found_field.formatted_value;
        }

        if (
          this.formBuilderModel[connectionId] &&
          this.formBuilderModel[connectionId].hasOwnProperty('multi_line') &&
          this.formBuilderModel[connectionId].multi_line === true
        ) {
          found_field.multi_line = true;
        } else {
          found_field.multi_line = false;
        }

        this.formBuilderModel[connectionId].is_valid = found_field.is_valid;
        this.formBuilderModel[connectionId].is_validated =
          found_field.is_validated;
        this.$emit('checkFieldInvalid', found_field);
      } catch (err) {
        logError(err);
      }
    },

    setApiData(data: any) {
      this.record = data;
      this.$forceUpdate();
    },

    windowResize() {
      setTimeout(() => {
        let imageElm = $('#image_container') as HTMLElement;
        this.imageWidth = imageElm.offsetWidth;
        this.imageHeight = imageElm.offsetHeight;
        this.refreshAnnotationView++;
      }, 20);
    },

    currentPage() {
      return this.page;
    },
    prevImage() {
      let new_page_number = this.page - 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    nextImage() {
      let new_page_number = this.page + 1;
      let path = this.getImagePath(new_page_number);
      this.updateImage(new_page_number, path);
    },

    getImagePath(page_number: number) {
      let path = '';
      for (const [key, image] of Object.entries(this.images)) {
        let imageInfo = image as dynamicObj;
        if (imageInfo.pageNumber === page_number) {
          path = imageInfo.path;
        }
      }

      return path;
    },

    updateImage(page_number: number, path: string) {
      if (!path || path === '') {
        return;
      }
      this.image = this.baseUrl + '/' + cleanUpImagePath(path);
      this.page = page_number;
    },
    handleImageBaseURL() {
      if (!this.record.images[0]) {
        return;
      }
      if (this.record.images[0].path.match(/doc2/g)) {
        this.baseUrl = DOC2API_URL;
      }
    },
    updateApiData(e: any) {
      if (!e.detail) {
        return;
      }
      this.record = e.detail;
    },
    async notifyRequisition() {
      if (this.isReadOnly) {
        return;
      }

      if (!this.validateData()) {
        return false;
      }

      try {
        this.showLoading();
        const data: any = JSON.parse(JSON.stringify(this.record));
        const response = await documentDetailApiService.notifyReq(data);
        if (response.success === false) {
          throw response;
        }

        notify.success(this.$t('notify_req_success'));
        this.assign_user_error = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      return true;
    },
    // TODO::Permission  acls needs to be applied here
    async saveData() {
      if (this.isReadOnly) {
        return;
      }

      if (!this.validateData()) {
        return false;
      }

      try {
        this.showLoading();
        const response = await this.saveDocument(this.docId);
        if (response.success === false) {
          throw response;
        }

        // The save may have moved this document onto another layout.
        if (await this.refreshResolvedLayout()) {
          await this.buildModelForLayout();
          await this.$nextTick();
        }

        notify.success(this.$t('MSG_SAVE'));
        this.assign_user_error = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      return true;
    },

    validateData() {
      let validate = true;
      if (
        isUndefinedOrNull(this.record.assigned_to) &&
        isUndefinedOrNull(this.record.assigned_to_group_id)
      ) {
        notify.error(this.$t('ASSIGN_USER_TO_PROCEED'));
        this.assign_user_error = true;
        validate = false;
      }
      return validate;
    },
    async setInReview() {
      try {
        if (this.isReadOnly) {
          return;
        }

        this.showLoading();
        await this.saveData();
        await this.setDocumnetStatus(CONSTANTS.in_review);
        this.$router.push('/dashboard');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async setDocumnetStatus(status: string) {
      try {
        const response = await documentDetailApiService.set_document_status(
          this.docId,
          {
            status: status,
          },
        );

        if (response.success === false) {
          throw { message: response.message };
        }

        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async goToFieldValidation() {
      try {
        if (this.isReadOnly) {
          return;
        }
        this.showLoading();
        await this.saveData();
        await this.setDocumnetStatus(CONSTANTS.ready_for_validation);
        this.$router.push('/field_validation_v1/' + this.docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async goToSummery() {
      if (!this.validateApprovalData()) {
        return;
      }

      try {
        this.showLoading();
        if (!(await this.saveData())) {
          return;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }

      this.$router.push('/summary/' + this.docId);
    },
    async acceptRequest() {
      if (!this.validateApprovalData()) {
        return;
      }

      if (this.model[approval_stamp]) {
        let new_page_number = this.images.length;
        let path = this.getImagePath(new_page_number);
        this.updateImage(new_page_number, path);
        if (this.page === this.images.length) {
          let stamp_name =
            this.locale === 'de'
              ? 'approved_stamp_de'
              : ('approved_stamp_en' as string);
          await (this.$refs.child_comp as any).addStampAnnotation(stamp_name);
        }
      }
      this.record.first_approver = this.record.assigned_to;

      this.updateRequest('approve');
    },

    rejectRequest() {
      if (!this.second_approval) {
        delete this.record.first_approver;
      }

      this.updateRequest('reject');
    },

    rejectAndCorrect() {
      this.updateRequest(CONSTANTS.reject_and_correct);
    },

    approveAndCorrect() {
      this.updateRequest(CONSTANTS.approve_and_correct);
    },

    async updateRequest(request_type: string) {
      try {
        if (this.isReadOnly) {
          return;
        }
        if (!this.validateData()) {
          return;
        }

        this.showLoading();
        let data = { request_type: request_type } as any;
        if (this.record.notes) {
          data['notes'] = this.record.notes;
        }

        const response = await this.approveOrRejectDocument(this.docId, data);

        if (response.success === false) {
          const approvalData = this.record.document_approval;
          if (
            approvalData &&
            approvalData.approval_requests &&
            approvalData.approval_requests.length > 0 &&
            response.error_code == 'RETURN_TO_DASHBOARD'
          ) {
            this.$router.push('/dashboard');
            return;
          }
          throw response;
        }

        notify.success(this.$t('MSG_SAVE'));
        if (
          request_type === CONSTANTS.reject_and_correct ||
          request_type === CONSTANTS.approve_and_correct
        ) {
          this.$router.push({
            path: `/field_validation_v1/${this.docId}`,
            query: { showApprovalHistory: 'true' },
          });
          return;
        } else {
          this.$router.push('/dashboard');
          return;
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);

        if (err && err.error_code == 'DOC_PENDING_TASKS') {
          notify.warning(msg, { duration: 10000 });
        } else {
          notify.error(msg);
        }
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async exportAndNext() {
      try {
        if (this.isReadOnly) {
          return;
        }
        if (!this.validateData()) {
          return;
        }

        this.showLoading();
        const requestParams = { request_type: 'approve' };
        const response = await this.approveOrRejectDocument(
          this.docId,
          requestParams,
        );

        if (!response.success && response.error_code != 'RETURN_TO_DASHBOARD') {
          throw response;
        }

        // load dashboard filters
        await this.getOrderBy();
        this.getSavedFilters();
        let queryParams = await this.makeQueryParamFromFilters();
        queryParams = '?current_doc_id=' + this.docId + queryParams;

        const nextDocument =
          await documentDetailApiService.getNextDocument_v2(queryParams);

        if (!nextDocument.success) {
          if(nextDocument.message === 'No document found') {
            this.confirmRedirection = true;
            return;
          }
          throw { 'message' : nextDocument.message };
        }

        this.rowClick(nextDocument.data, false, this.isMediUser());
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    addNewLog(e: any) {
      if (!e || !e.detail) {
        return;
      }

      // Logs refresh automatically when activity_stream panel is opened
    },
    downloadFile() {
      downloadDocumentFile(this.docId, this.record.filename, this.tokenQueryParam, '.pdf');
    },
    routeToListPendingApproval() {
      this.removeDashboardFilters();
      // this.savedDashboardFilters('?filter=current-year&skip=0&limit=10&status=' + this.filter_status)
      this.$router.push('/dashboard');
    },
    async renderPendingRecordsCountView() {
      try {
        let response: any;
        let queryParams =
          '?filter=current-year&skip=0&limit=100&status=' + this.filter_status;
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(api.get_dashboard_data + queryParams),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (!response.data.documents) {
          throw { message: 'no pending documents from server' };
        }

        this.pending_approval_doc_count = response.data.documents.length;
        if (this.pending_approval_doc_count < 0) {
          this.pending_approval_doc_count = 0;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async renderNextPrevLinkBtns() {
      try {
        let response: any;
        let token: string = await getAuthorizationToken();

        response = await axios.get(
          addOrgIdQueryString(
            api.get_next_document +
              this.docId +
              '?doc_type=' +
              this.record.doc_type +
              '&status=' +
              this.filter_status +
              '&sort_attr=created_on',
          ),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (response.data.success === false) {
          throw {
            message: 'cannot get response related to next or prev record',
          };
        }

        if (response.data.has_next && response.data.next_id) {
          this.next_record = response.data.next_id;
        }

        if (response.data.has_previous && response.data.previous_id) {
          this.prev_record = response.data.previous_id;
        }
      } catch (err) {
        logError('something went wrong while loading document logs');
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    checkValidStatus() {
      if (isEmptyString(this.doc_status)) {
        return;
      }

      if (
        this.doc_status !== this.filter_status &&
        this.doc_status !== CONSTANTS.in_review &&
        this.doc_status !== CONSTANTS.approved_pending_second_approval
      ) {
        this.error = true;
        this.error_message = 'invalid_status';
      }
    },

    routeTo(direction: string) {
      let route = 'ready-for-approval';
      if (this.second_approval) {
        route = 'ready-for-second-approval';
      }

      if (direction === 'prev' && this.prev_record) {
        this.$router.push({
          path: '/' + route + '/' + this.prev_record,
          replace: true,
        });
      }

      if (direction === 'next' && this.next_record) {
        this.$router.push('/' + route + '/' + this.next_record);
      }
    },

    updateValue(key: any, value: any) {
      if (key == 'font') {
        this.selectFont = value;
      } else if (key == 'color') {
        this.selectColor = value;
      } else if (key == 'size') {
        this.selectFontSize = value;
      }
    },

    stampAddClicked() {
      (this.$refs.child_comp as any).addTemplateAnnotation(this.selectedStamp);
    },
    getApprovalInfoObj(approvalInfoParam: any) {
      const lineFieldValue = approvalInfoParam.lineFieldValue
        ? approvalInfoParam.lineFieldValue
        : 0;
      const poFieldValue = approvalInfoParam.poFieldValue
        ? approvalInfoParam.poFieldValue
        : 0;

      let approvedAmount = 0;
      let rejectedAmount = 0;

      if (approvalInfoParam.status == approvalInfoStatus.approved) {
        approvedAmount = lineFieldValue;
        rejectedAmount = 0;
      }

      if (approvalInfoParam.status == approvalInfoStatus.rejected) {
        approvedAmount = poFieldValue;
        rejectedAmount = lineFieldValue - poFieldValue;
      }

      return {
        approval_required: true,
        approval_status: approvalInfoParam.status,
        approved_or_rejected_by: approvalInfoParam.currentUserId,
        approved_or_rejected_at: approvalInfoParam.currentDateTime,
        approved_amount: approvedAmount,
        rejected_amount: rejectedAmount,
        // 'approved_or_rejected_reason': 'reason for approval or rejection'
      };
    },
    handleApprover(data: dynamicObj) {
      data['first_approver'] = this.fillFirstApprover();
      data['assigned_to'] = this.createEmptyField(
        'assigned_to',
        '',
        this.record.assigned_to,
      );
      return data;
    },
    makeModel() {
      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record?.fields) {
          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
          });

          this.handleApprover(data);
          // prepare the list with updated field settings
          let layoutSettings = this.getUpdatedFieldSettings();

          for (let [index, fieldDef] of this.formLayout.entries()) {
            let field_name = fieldDef.hasOwnProperty('field_name')
              ? fieldDef.field_name
              : fieldDef.name;

            // replace setting with updated field settings
            if (layoutSettings.hasOwnProperty(field_name)) {
              fieldDef = Object.assign(
                fieldDef,
                this.cleanLayoutSettings(layoutSettings[field_name]),
              );
            }

            this.prepareModel(fieldDef, data[field_name], field_name);

          }
          this.$forceUpdate();
        }

        resolve('done');
      });
    },
    makeModel_v2() {
      return new Promise((resolve, reject) => {
        let data: any = {};
        if (this.record?.fields) {
          this.record.fields.forEach((value: any, index: any) => {
            data[value.name] = value;
          });

          // handle Charges group validation
          // this.handleChargesGroupValidation(data);

          this.handleApprover(data);

          this.transformDataToV2(this.formLayout);

          // prepare the list with updated field settings
          let layoutSettings = this.getUpdatedFieldSettings();

          for (let [index, group] of this.formLayout.entries()) {
            for (let fieldDef of group.rows) {
              let field_name = fieldDef.hasOwnProperty('field_name')
                ? fieldDef.field_name
                : fieldDef.name;

              // replace setting with updated field settings
              if (layoutSettings.hasOwnProperty(field_name)) {
                fieldDef = Object.assign(
                  fieldDef,
                  this.cleanLayoutSettings(layoutSettings[field_name]),
                );
              }

              this.prepareModel(fieldDef, data[field_name], field_name);
            }
          }
          this.$forceUpdate();
        }

        resolve('done');
      });
    },
    handleChargesGroupValidation(data: any) {
      for (let [index, group] of this.formLayout.entries()) {
        if (group.name != GROUP_NAMES.charges) {
          continue;
        }

        for (let i = 0; i < group.rows.length; i = i + 3) {
          let poFieldName = group.rows[i].field_name;
          let lineFieldName = group.rows[i + 1].field_name;

          if (
            !data.hasOwnProperty(poFieldName) ||
            !data.hasOwnProperty(lineFieldName)
          ) {
            continue;
          }

          // if(data[poFieldName].value != data[lineFieldName].value) {

          data[lineFieldName].input_error = 'invalid-input';

          const approvalInfoParams = {
            status: approvalInfoStatus.pending,
            currentUserId: null,
            currentDateTime: null,
            lineFieldValue: Number(data[lineFieldName].value),
            poFieldValue: Number(data[poFieldName].value),
          };

          data[lineFieldName]['approval_info'] =
            this.getApprovalInfoObj(approvalInfoParams);
          // }
        }

        break;
      }
    },
    prepareModel(fieldDef: any, field_model: any, field_name: string) {
      if (!field_model) {
        field_model = this.createEmptyField(field_name, fieldDef.input_type);
      }
      let fieldType = fieldDef.input_type
        ? fieldDef.input_type
        : fieldDef.fieldType;
      if (!fieldType) {
        return;
      }

      if (
        !fieldDef.hasOwnProperty('tabIndex') ||
        isUndefinedOrNull(fieldDef.tabIndex)
      ) {
        fieldDef.tabIndex = 0;
      }

      this.cleanCheckboxValue(field_model, fieldType.toLowerCase());

      this.formBuilderModel[field_name] = {};
      this.formBuilderConfigModel[field_name] = {};

      this.formBuilderModel[field_name] = Object.assign({}, field_model);
      this.formBuilderConfigModel[field_name] = Object.assign({}, fieldDef);

      if (field_model.hasOwnProperty('is_required')) {
        this.formBuilderConfigModel[field_name].is_required =
          field_model.is_required;
      }

      if (field_name == 'first_approver' && this.second_approval) {
        this.formBuilderConfigModel[field_name].translation_key =
          'first_approver';
      }

      this.handleListofValues(field_name);
    },
    cleanCheckboxValue(field_model: any, type: string) {
      if (type != 'checkbox' && field_model.fieldType != 'CheckBox') {
        return;
      }

      if (field_model.formatted_value == 'true' || field_model.formatted_value == true || field_model.formatted_value == 'Y') {
        field_model.formatted_value = true;
      } else {
        field_model.formatted_value = false;
      }
    },
    handleListofValues(field_name: string) {
      if (!this.formBuilderConfigModel[field_name].list_of_values) {
        return;
      }

      this.addNameToLovList(
        this.formBuilderConfigModel[field_name].list_of_values,
      );
    },
    cleanLayoutSettings(layoutSetting: any): any {
      delete layoutSetting.name;
      delete layoutSetting.field;
      delete layoutSetting.field_name;
      delete layoutSetting.field_type;

      // remove the title as it might be changed from layout builder
      delete layoutSetting.title;
      delete layoutSetting.translation_key;
      delete layoutSetting.is_readonly;

      return layoutSetting;
    },

    async getFormBuilderLayout(layoutType = '') {
      try {
        await this.getLayoutTemplate({
          doc_id: this.docId,
          layout_type: layoutType,
          doc_type: this.record.doc_type,
          doc_origin: this.record.doc_origin,
          include_layout_json: true,
        });

        await this.buildModelForLayout();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

    async buildModelForLayout() {
      if (!this.formLayout) {
        return;
      }

      if (this.model[approve_before_export_v2]) {
        await this.makeModel_v2();
      } else {
        await this.makeModel();
      }
    },
    setRowReadOnly(row: any) {
      row.is_readonly = true;
    },
    setRowHidden(row: any) {
      row.is_hidden = true;
      row.visibile = false;
    },
    applyPermissions(field: any) {
      if (!this.field_permissions) {
        return;
      }
      if (!this.formLayout) {
        return;
      }
      const user_id = this.getUserId();
      if (field.fieldType != 'TextInput') {
        return;
      }
      if (!this.field_permissions[field.id]) {
        return;
      }
      let field_permissions_key = this.field_permissions[field.id].access;

      if (isUserAdmin()) {
        field_permissions_key = 32;
      }
      switch (field_permissions_key) {
        case 0:
          this.setRowHidden(field);
          break;
        case 1:
          this.setRowReadOnly(field);
          break;
        case 2:
          field.is_readonly = false;
          break;
        case 4:
          if (user_id != this.record.assigned_to) {
            this.setRowReadOnly(field);
            break;
          }
          field.is_readonly = false;
          break;
        case 8:
          if (user_id != this.record.assigned_to) {
            this.setRowHidden(field);
            break;
          }
          field.is_readonly = false;
          field.is_hidden = false;
          break;
        case 16:
          let approver = '';
          if (this.second_approval) {
            approver = this.formBuilderModel['second_approver'].formatted_value;
          } else {
            approver = this.formBuilderModel['first_approver'].formatted_value;
          }
          if (user_id != approver) {
            this.setRowHidden(field);
            break;
          }
          field.is_readonly = false;
          field.is_hidden = false;
          break;
        case 32:
          if (!isUserAdmin()) {
            this.setRowHidden(field);
            break;
          }
          field.is_readonly = false;
          field.is_hidden = false;
          break;
      }
    },
    getUpdatedFieldSettings(): any {
      let layoutSettings: any = {};
      let groups = JSON.parse(JSON.stringify(this.record.layout.groups));

      groups.forEach((group: any, index: any) => {
        group.rows.forEach((row: any, index: any) => {
          row.forEach((subRow: any, index: any) => {
            let field_name = subRow.field_name;
            layoutSettings[field_name] = subRow;
          });
        });
      });

      return layoutSettings;
    },
    updateModel(newField: any) {
      return;
    },

    restoreBeforeLeave() {
      this.record = {};
      this.error = false;
      this.error_message = '';
      this.doc_status = '';
      this.page = 1;
    },

    getReadOnlyStatus(element: dynamicObj) {
      if (element.name.startsWith('tab_panel_tables_')) {
        return true;
      }

      if (this.isReadOnly) {
        return true;
      }

       
      return element.is_readonly;
    },
    validateApprovalData() {
      // TODO need to validate the charges group fields right now only table fields are validated

      let isValid = true;
      if (this.isTypeQuote()) {
        // validate only for quotes
        isValid = this.quotesTableIdsNeedUserAction.length == 0;
      } else {
        isValid = this.validatePOMathAprrovalSatus();
      }

      if (!isValid) {
        notify.error(
          this.$t('VALIDATION_REQUIRED_FOR_TABLE'),
        );
      }
      return isValid;
    },
    validatePOMathAprrovalSatus() {
      let isValid = false;
      if (
        !this.record.po_multi_matched ||
        this.record.po_multi_matched.length == 0
      ) {
        return true;
      }
      for (let [index, data] of this.record.po_multi_matched.entries()) {
        if (data.hasOwnProperty('sub_lines')) {
          // multi po and one line
          isValid = this.multiPoToOneLine(data);
        } else if (data.hasOwnProperty('table_lines')) {
          // one po and multi line
          isValid = this.onePoToOneLine(data);
        } else {
          // one po and one line
          isValid = this.onePoToOneLine(data);
        }

        if (!isValid) {
          break;
        }
      }
      return isValid;
    },
    multiPoToOneLine(data: any) {
      let isValid = false;

      for (const subline of data.sub_lines) {
        isValid = this.onePoToOneLine(subline);

        if (!isValid) {
          break;
        }
      }

      return isValid;
    },
    onePoToOneLine(data: any) {
      let isValid = true;

      const approvalData = this.record.document_approval;

      if (data.approval_info && Object.entries(data.approval_info).length > 0) {
        for (const [key, field] of Object.entries(data.approval_info)) {
          if (
            (field as any).approval_required &&
            !(field as any).approval_status
          ) {
            if (
              approvalData &&
              approvalData.approval_requests &&
              approvalData.approval_requests.length > 0 &&
              !this.checkForApprovalpermission(key)
            ) {
              continue;
            }
            isValid = false;
            break;
          }
        }
      }

      if (!data.additional_charges || data.additional_charges.length == 0) {
        return isValid;
      }

      for (let charge of data.additional_charges) {
        if (
          charge.approval_info &&
          charge.approval_info.approval_required &&
          !charge.approval_info.approval_status
        ) {
          const originalName = this.getChargesNameByCostingElement(
            charge.costing_element,
          );
          if (
            approvalData &&
            approvalData.approval_requests &&
            approvalData.approval_requests.length > 0 &&
            !this.checkForApprovalpermission(originalName)
          ) {
            continue;
          }
          isValid = false;
        }
      }

      return isValid;
    },
    validatePageNumber() {
      if (!this.page) {
        this.page = 1;
        return;
      }

      if (this.page > this.images.length) {
        this.page = this.images.length;
      }

      this.pageChanged(this.page);
    },
    pageChanged(number: any) {
      if (!number || number == 0 || number > this.lastPageItem) {
        return;
      }

      this.updateImage(
        number,
        cleanUpImagePath(this.record.images[number - 1].path),
      );
    },

    goToDashboard() {
      this.$router.push('/dashboard');
    },

    setTriggerDocumentLock(isLocked: boolean) {
      this.trigger_document_lock = isLocked;
    },
  },
  setup() {
    const $q = useQuasar();
    let data: any = [];
    const dropdownStore = useDropdownStore();
    const { getSelectedLanguage } = dropdownStore;

    const tolgee = useTolgee(['language']);
    const locale = computed(() => tolgee.value.getLanguage() || 'en');

    const doc_store = useDocumentStore();
    const {
      approveOrRejectDocument,
      getDocumentById,
      getDocAnnotations,
      saveDocument,
      resetDocStore,
      checkForApprovalpermission,
      getChargesNameByCostingElement,
      removeCache,
      isTypeQuote,
    } = doc_store;
    const {
      record,
      script_error_count,
      doc_status,
      error,
      error_message,
      page,
      tablePermissions,
      fieldPermissions,
      document_version,
      quotesTableIdsNeedUserAction,
      hasApiData,
    } = storeToRefs(doc_store);
    const user_store = useUserStore();
    const { getUserId, isMediUser } = user_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    const dashboard_store = useDashboardStore();
    const {
      removeSavedFilters: removeDashboardFilters,
      saveFilters: savedDashboardFilters,
      getOrderBy,
      getSavedFilters,
      makeQueryParamFromFilters,
    } = dashboard_store;

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    const form_builder_store = useFormBuilderStore();
    form_builder_store.$reset();
    const {
      second_approval,
      formBuilderModel,
      formLayout,
      formBuilderConfigModel,
    } = storeToRefs(form_builder_store);
    const { transformDataToV2, getLayoutTemplate, refreshResolvedLayout } =
      form_builder_store;

    const doc_attribute_store = useDocAttributesStore();
    const { model } = storeToRefs(doc_attribute_store);
    const { fetchAttributes, getDocTypeAllSettings } = doc_attribute_store;

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock, acquireDocLock } = doc_lock_store;
    const { doc_lock } = storeToRefs(doc_lock_store);

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { addNameToLovList, populateListsAndValues } =
      field_values_setting_store;

    const { current_sidebar, sidebarWidthClass, rightSectionClass, toggleSideBar } = useSidebarPanel();

    return {
      current_sidebar,
      sidebarWidthClass,
      rightSectionClass,
      toggleSideBar,
      model,
      hasApiData,
      user_settings,
      locale,
      saveDocument,
      getDocumentById,
      fetchAttributes,
      getDocAnnotations,
      getLayoutTemplate,
      refreshResolvedLayout,
      getDocTypeAllSettings,
      isMediUser,
      getUserId,
      getOrderBy,
      removeCache,
      isTypeQuote,
      getSavedFilters,
      addNameToLovList,
      startSettingsFetch,
      savedDashboardFilters,
      populateListsAndValues,
      removeDashboardFilters,
      approveOrRejectDocument,
      makeQueryParamFromFilters,
      checkForApprovalpermission,
      getChargesNameByCostingElement,

      approve_before_export,
      tokenQueryParam,
      getTokenQueryParam: refreshTokenParam,
      doc_status,
      page,
      error,
      error_message,
      record,
      dropdownStore,
      image: '',
      images: data,
      baseUrl: DOC2API_URL,
      isReadOnly: false,
      usersList: ref([] as any),
      tablePermissions,
      fieldPermissions,
      assign_user_error: ref(false),
      field_permissions: ref({} as any),
      general_permissions: ref({} as any),
      pending_approval_doc_count: ref(0),
      next_record: ref(''),
      confirmRedirection: ref(false),
      display_doc_script_logs: ref(false),
      script_error_count,
      prev_record: ref(''),
      second_approval,
      showNotification(message: string) {
        notify.info(message);
      },

      showFontMenu: ref(true),
      showStampMenu: ref(false),
      selectColor: ref('#000000'),
      selectFont: ref('Helvetica'),
      fontlist: [
        'Helvetica',
        'Times New Roman',
        'Arimo',
        'Caladea',
        'Carlito',
        'Cousine',
        'Liberation Serif',
        'Arial',
      ],
      selectFontSize: ref(20),
      fontSizes: [] as any,
      showDoc: ref(false),

      selectedStamp: ref(''),
      // stamps: [
      //   'annotation/annotation_stamps/approved_stamp_de.svg',
      //   'annotation/annotation_stamps/rejected_stamp_de.svg',
      //   'annotation/annotation_stamps/approved_stamp_en.svg',
      //   'annotation/annotation_stamps/rejected_stamp_en.svg'
      // ],
      screenmode: ref('annotate'),
      formLayout,
      formBuilderModel,
      formBuilderConfigModel,
      trigger_document_lock: ref(false),
      quotesTableIdsNeedUserAction,
      approval_history,
      document_version,
      getSelectedLanguage,
      transformDataToV2,
      releaseDocLock,
      acquireDocLock,
      resetDocStore,
      doc_lock,
    };
  },
});
</script>

